//! Analytics reports generated by the process tracker instead of the reporting Lambdas.
//!
//! A report runs in two stages so a failed delivery never regenerates the file: the CSV is built
//! and uploaded, then the download link is sent by webhook (when the request names a `return_url`)
//! or by email. The webhook keeps the payload shape and `X-Webhook-Signature-512` header that
//! `weekly_payment_report_generator_step_2` sent.

use analytics::{
    enums::AuthInfo,
    errors::AnalyticsError,
    lambda_utils::invoke_lambda,
    reports::{self, payments::PaymentReportCursor, ReportScope},
    ReportBackend,
};
use api_models::analytics::{GenerateReportRequest, ReportRequest};
use common_utils::{
    crypto::{HmacSha512, SignMessage},
    date_time,
    errors::CustomResult,
    id_type,
    pii::Email,
    request::RequestContent,
};
use error_stack::{report, ResultExt};
use hyperswitch_masking::PeekInterface;
use router_env::{instrument, tracing};

use crate::{
    logger,
    routes::SessionState,
    services::{self, ApplicationResponse},
    types::storage,
};

pub(crate) const ANALYTICS_REPORT_TASK: &str = "ANALYTICS_REPORT";
const ANALYTICS_REPORT_TAGS: [&str; 2] = ["ANALYTICS", "REPORT"];

/// Every multipart part except the last must be at least 5 MB.
const MULTIPART_PART_SIZE: usize = 5 * 1024 * 1024;

/// The Lambda gave the merchant's endpoint 10 seconds.
const WEBHOOK_TIMEOUT_SECS: u64 = 10;

#[derive(Clone, Copy, Debug, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum AnalyticsReportType {
    /// The Lambda's `v1_payments` report.
    V1Payments,
}

impl AnalyticsReportType {
    /// Names the report in its file key, as the Lambda's `report_type` did.
    fn file_label(self) -> &'static str {
        match self {
            Self::V1Payments => "v1_payments",
        }
    }

    /// `data.report_type` in the webhook.
    fn webhook_label(self) -> &'static str {
        match self {
            Self::V1Payments => "payment_report",
        }
    }

    /// The report's name in the email, after the environment label.
    #[cfg(feature = "email")]
    fn email_name(self) -> &'static str {
        match self {
            Self::V1Payments => "Payments",
        }
    }

    /// What the report covers, as worded in the email body.
    #[cfg(feature = "email")]
    fn email_description(self) -> &'static str {
        match self {
            Self::V1Payments => "payments",
        }
    }
}

#[derive(Clone, Debug, serde::Serialize, serde::Deserialize)]
pub struct AnalyticsReportTrackingData {
    pub job_id: String,
    pub report_type: AnalyticsReportType,
    /// `time_range.end_time` is always set: an open range is closed at the time of the request.
    pub request: ReportRequest,
    pub auth: AuthInfo,
    /// Whose key store decrypts the webhook signing key. `None` for an organization report, which
    /// the Lambda sent unsigned.
    pub key_store_merchant_id: Option<id_type::MerchantId>,
    /// The requesting user, or the first address in `request.emails` for API key requests.
    pub email: Email,
    pub file_key: String,
    /// Written once the multipart upload starts, so a retry can discard the abandoned parts.
    pub upload_id: Option<String>,
    /// Set once the file is complete; from then on retries only redo delivery.
    pub row_count: Option<usize>,
    /// Recipients already emailed, so a retry does not mail them twice.
    #[serde(default)]
    pub delivered_to: Vec<Email>,
}

impl AnalyticsReportTrackingData {
    fn start_time(&self) -> time::PrimitiveDateTime {
        self.request.time_range.start_time
    }

    fn end_time(&self) -> time::PrimitiveDateTime {
        self.request
            .time_range
            .end_time
            .unwrap_or(self.request.time_range.start_time)
    }

    /// The report's file name, also offered as the download's name. The range is written without
    /// separators so the name stays valid on every file system.
    fn file_name(&self) -> String {
        let label = self.report_type.file_label();
        let compact = |value| {
            date_time::format_date(value, date_time::DateFormat::YYYYMMDDHHmmss)
                .unwrap_or_else(|_| value.to_string())
        };
        format!(
            "{label}_report_{}_{}.csv",
            compact(self.start_time()),
            compact(self.end_time()),
        )
    }

    /// The Lambda's `org_id` / `merchant_id` / `profile_id`, which name the report in its file key
    /// and webhook. A connected merchant is named by its platform, as the Lambda did.
    fn owner(&self) -> (&str, Option<&str>, Option<&str>) {
        match &self.auth {
            AuthInfo::OrgLevel { org_id } => (org_id.get_string_repr(), None, None),
            AuthInfo::MerchantLevel {
                org_id,
                merchant_ids,
                ..
            } => (
                org_id.get_string_repr(),
                merchant_ids.first().map(|id| id.get_string_repr()),
                None,
            ),
            AuthInfo::ProfileLevel {
                org_id,
                merchant_id,
                profile_ids,
                ..
            } => (
                org_id.get_string_repr(),
                Some(merchant_id.get_string_repr()),
                profile_ids.first().map(|id| id.get_string_repr()),
            ),
        }
    }
}

/// Starts a payment report on the backend `report_download_config.payment_backend` selects.
pub async fn generate_payment_report(
    state: &SessionState,
    request: GenerateReportRequest,
) -> CustomResult<ApplicationResponse<()>, AnalyticsError> {
    let config = &state.conf.report_download_config;
    match config.payment_backend {
        ReportBackend::Lambda => {
            let json_bytes =
                serde_json::to_vec(&request).map_err(|_| AnalyticsError::UnknownError)?;
            invoke_lambda(&config.payment_function, &config.region, &json_bytes)
                .await
                .map(ApplicationResponse::Json)
        }
        ReportBackend::ProcessTracker => {
            #[cfg(feature = "v1")]
            {
                enqueue_report(state, AnalyticsReportType::V1Payments, request)
                    .await
                    .map(ApplicationResponse::Json)
            }
            // v2 reports choose between `v2_payments` and `revenue_recovery`, not ported yet.
            #[cfg(feature = "v2")]
            {
                Err(report!(AnalyticsError::NotImplemented(
                    "Generating v2 payment reports on the process tracker"
                )))
            }
        }
    }
}

#[instrument(skip_all, fields(report_type = ?report_type))]
async fn enqueue_report(
    state: &SessionState,
    report_type: AnalyticsReportType,
    request: GenerateReportRequest,
) -> CustomResult<(), AnalyticsError> {
    if !reports::is_supported(&state.pool) {
        return Err(report!(AnalyticsError::NotImplemented(
            "Report generation without a Postgres analytics pool"
        )));
    }

    let GenerateReportRequest {
        request: mut report_request,
        merchant_id,
        auth,
        email,
        // Not persisted: the signing key is read again from the merchant's key store on delivery.
        payment_response_hash_key: _,
    } = request;

    let now = date_time::now();
    report_request.time_range.end_time = Some(report_request.time_range.end_time.unwrap_or(now));

    let job_id = common_utils::generate_id(crate::consts::ID_LENGTH, "report");
    let mut tracking_data = AnalyticsReportTrackingData {
        job_id: job_id.clone(),
        report_type,
        request: report_request,
        auth,
        key_store_merchant_id: merchant_id,
        email,
        file_key: String::new(),
        upload_id: None,
        row_count: None,
        delivered_to: Vec::new(),
    };
    tracking_data.file_key = file_key(
        &state
            .conf
            .report_download_config
            .process_tracker
            .file_key_prefix,
        &tracking_data,
    );

    let runner = storage::ProcessTrackerRunner::AnalyticsReportWorkflow;
    let process_tracker_entry = storage::ProcessTrackerNew::new(
        format!("{runner}_{ANALYTICS_REPORT_TASK}_{job_id}"),
        ANALYTICS_REPORT_TASK,
        runner,
        ANALYTICS_REPORT_TAGS,
        tracking_data,
        None,
        now,
        common_types::consts::API_VERSION,
        common_enums::ApplicationSource::Main,
    )
    .change_context(AnalyticsError::UnknownError)
    .attach_printable("Failed to build the analytics report process tracker entry")?;

    state
        .store
        .insert_process(process_tracker_entry)
        .await
        .change_context(AnalyticsError::UnknownError)
        .attach_printable("Failed to enqueue the analytics report")?;

    logger::info!(job_id = %job_id, "Analytics report enqueued");
    Ok(())
}

/// The Lambda's key, with the job id added so two requests for the same range cannot overwrite
/// each other's file.
fn file_key(prefix: &str, tracking_data: &AnalyticsReportTrackingData) -> String {
    let (org_id, merchant_id, profile_id) = tracking_data.owner();
    let owner = [Some(org_id), merchant_id, profile_id]
        .into_iter()
        .flatten()
        .collect::<Vec<_>>()
        .join("/");
    format!(
        "{prefix}/{owner}/{}/{}/{}",
        tracking_data.report_type.file_label(),
        tracking_data.job_id,
        tracking_data.file_name(),
    )
}

struct UploadProgress {
    buffer: Vec<u8>,
    parts: Vec<(i32, String)>,
}

/// Writes the report to `file_key` and returns the number of rows in it.
pub(crate) async fn generate_report_file(
    state: &SessionState,
    tracking_data: &AnalyticsReportTrackingData,
    upload_id: &str,
) -> CustomResult<usize, AnalyticsError> {
    let page_size = state
        .conf
        .report_download_config
        .process_tracker
        .page_size
        .max(1);
    let scope = ReportScope::from(&tracking_data.auth);
    let file_key = tracking_data.file_key.as_str();

    let mut progress = UploadProgress {
        buffer: match tracking_data.report_type {
            AnalyticsReportType::V1Payments => reports::payments::csv_header(),
        },
        parts: Vec::new(),
    };
    let mut row_count = 0;
    let mut cursor: Option<PaymentReportCursor> = None;

    loop {
        let page = match tracking_data.report_type {
            AnalyticsReportType::V1Payments => {
                reports::payments::fetch_page(
                    &state.pool,
                    &scope,
                    tracking_data.start_time(),
                    tracking_data.end_time(),
                    cursor.as_ref(),
                    page_size,
                )
                .await?
            }
        };

        row_count += page.row_count;
        progress.buffer.extend_from_slice(&page.csv);
        if progress.buffer.len() >= MULTIPART_PART_SIZE {
            upload_buffered_part(state, file_key, upload_id, &mut progress).await?;
        }

        match page.next_cursor {
            Some(next) => cursor = Some(next),
            None => break,
        }
    }

    // The final part is the only one allowed below the minimum size, and always holds the header
    // when the report is empty.
    if !progress.buffer.is_empty() {
        upload_buffered_part(state, file_key, upload_id, &mut progress).await?;
    }

    state
        .file_storage_client
        .complete_multipart_upload(file_key, upload_id, progress.parts)
        .await
        .change_context(AnalyticsError::UnknownError)
        .attach_printable("Failed to complete the analytics report upload")?;

    Ok(row_count)
}

async fn upload_buffered_part(
    state: &SessionState,
    file_key: &str,
    upload_id: &str,
    progress: &mut UploadProgress,
) -> CustomResult<(), AnalyticsError> {
    let part_number = i32::try_from(progress.parts.len() + 1)
        .change_context(AnalyticsError::UnknownError)
        .attach_printable("Analytics report exceeded the maximum multipart part count")?;

    let e_tag = state
        .file_storage_client
        .upload_part(
            file_key,
            upload_id,
            part_number,
            std::mem::take(&mut progress.buffer),
        )
        .await
        .change_context(AnalyticsError::UnknownError)
        .attach_printable_lazy(|| {
            format!("Failed to upload analytics report part {part_number}")
        })?;

    progress.parts.push((part_number, e_tag));
    Ok(())
}

#[derive(serde::Serialize)]
struct ReportWebhook<'a> {
    org_id: &'a str,
    merchant_id: Option<&'a str>,
    #[serde(skip_serializing_if = "Option::is_none")]
    profile_id: Option<&'a str>,
    data: ReportWebhookData<'a>,
    event: &'static str,
}

#[derive(serde::Serialize)]
#[serde(untagged)]
enum ReportWebhookData<'a> {
    Completed {
        report_type: &'static str,
        start_date_utc: String,
        end_date_utc: String,
        download_url: &'a str,
        expires_in_hours: u32,
    },
    Failed {
        code: &'static str,
        message: &'static str,
    },
}

/// The webhook body, in the Lambda's payload shape.
fn webhook_body(
    tracking_data: &AnalyticsReportTrackingData,
    data: ReportWebhookData<'_>,
) -> CustomResult<Vec<u8>, AnalyticsError> {
    let (org_id, merchant_id, profile_id) = tracking_data.owner();
    let event = match data {
        ReportWebhookData::Completed { .. } => "report_generation.completed",
        ReportWebhookData::Failed { .. } => "report_generation.failed",
    };
    serde_json::to_vec(&ReportWebhook {
        org_id,
        merchant_id,
        profile_id,
        data,
        event,
    })
    .change_context(AnalyticsError::UnknownError)
    .attach_printable("Failed to serialize the analytics report webhook")
}

/// Sends the finished report to the requester, skipping email recipients an earlier attempt
/// already reached.
pub(crate) async fn deliver_report(
    state: &SessionState,
    process_id: &str,
    tracking_data: &mut AnalyticsReportTrackingData,
) -> CustomResult<(), AnalyticsError> {
    let expiry_hours = state
        .conf
        .report_download_config
        .process_tracker
        .download_url_expiry_hours;
    let download_url = state
        .file_storage_client
        .get_presigned_download_url(
            &tracking_data.file_key,
            std::time::Duration::from_secs(u64::from(expiry_hours) * 3600),
            Some(&tracking_data.file_name()),
        )
        .await
        .change_context(AnalyticsError::UnknownError)
        .attach_printable("Failed to sign the analytics report download URL")?;

    match tracking_data.request.return_url.clone() {
        Some(return_url) => {
            let body = webhook_body(
                tracking_data,
                ReportWebhookData::Completed {
                    report_type: tracking_data.report_type.webhook_label(),
                    start_date_utc: reports::format_timestamp(tracking_data.start_time()),
                    end_date_utc: reports::format_timestamp(tracking_data.end_time()),
                    download_url: download_url.as_str(),
                    expires_in_hours: expiry_hours,
                },
            )?;
            send_webhook(state, tracking_data, return_url.get_string_repr(), body).await
        }
        None => send_emails(state, process_id, tracking_data, download_url.as_str()).await,
    }
}

/// Tells the merchant's endpoint the report could not be produced. Tried once: by now the job has
/// already exhausted its retries.
pub(crate) async fn notify_report_failed(
    state: &SessionState,
    tracking_data: &AnalyticsReportTrackingData,
) -> CustomResult<(), AnalyticsError> {
    match tracking_data.request.return_url.as_ref() {
        Some(return_url) => {
            let body = webhook_body(
                tracking_data,
                ReportWebhookData::Failed {
                    code: "internal_server_error",
                    message: "We could not generate the report due to a internal server error. Please request the report again.",
                },
            )?;
            send_webhook(state, tracking_data, return_url.get_string_repr(), body).await
        }
        None => Ok(()),
    }
}

async fn send_webhook(
    state: &SessionState,
    tracking_data: &AnalyticsReportTrackingData,
    url: &str,
    body: Vec<u8>,
) -> CustomResult<(), AnalyticsError> {
    let mut request = services::RequestBuilder::new()
        .method(services::Method::Post)
        .url(url)
        .header("Content-Type", "application/json")
        .header("User-Agent", "Hyperswitch-Webhook/1.0");

    if let Some(hash_key) = payment_response_hash_key(state, tracking_data).await? {
        request = request.header(
            "X-Webhook-Signature-512",
            &webhook_signature(&hash_key, &body)?,
        );
    }

    let request = request.set_body(RequestContent::RawBytes(body)).build();
    let response = state
        .api_client
        .send_request(state, request, Some(WEBHOOK_TIMEOUT_SECS), false)
        .await
        .change_context(AnalyticsError::UnknownError)
        .attach_printable("Failed to reach the analytics report webhook endpoint")?;

    let status = response.status();
    match status.is_success() {
        true => {
            logger::info!(job_id = %tracking_data.job_id, %status, "Analytics report webhook delivered");
            Ok(())
        }
        false => Err(report!(AnalyticsError::UnknownError)).attach_printable(format!(
            "Analytics report webhook endpoint responded with {status}"
        )),
    }
}

/// Lowercase hex HMAC-SHA512 of the body, as the Lambda signed it.
fn webhook_signature(hash_key: &str, body: &[u8]) -> CustomResult<String, AnalyticsError> {
    HmacSha512
        .sign_message(hash_key.as_bytes(), body)
        .map(hex::encode)
        .change_context(AnalyticsError::UnknownError)
        .attach_printable("Failed to sign the analytics report webhook")
}

/// Read at delivery so the merchant's signing key is never written to the task.
async fn payment_response_hash_key(
    state: &SessionState,
    tracking_data: &AnalyticsReportTrackingData,
) -> CustomResult<Option<String>, AnalyticsError> {
    let Some(merchant_id) = tracking_data.key_store_merchant_id.as_ref() else {
        return Ok(None);
    };

    let key_store = state
        .store
        .get_merchant_key_store_by_merchant_id(
            merchant_id,
            &state.store.get_master_key().to_vec().into(),
        )
        .await
        .change_context(AnalyticsError::UnknownError)
        .attach_printable("Failed to read the merchant key store for the report webhook")?;

    crate::utils::get_payment_response_hash_key(
        state.store.as_ref(),
        &key_store,
        &tracking_data.auth,
    )
    .await
}

#[cfg(feature = "email")]
async fn send_emails(
    state: &SessionState,
    process_id: &str,
    tracking_data: &mut AnalyticsReportTrackingData,
    download_url: &str,
) -> CustomResult<(), AnalyticsError> {
    let config = &state.conf.report_download_config.process_tracker;
    let start = reports::format_timestamp(tracking_data.start_time());
    let end = reports::format_timestamp(tracking_data.end_time());
    let report_name = format!(
        "{} {}",
        config.email_env_label,
        tracking_data.report_type.email_name()
    );
    let email = ReportEmail {
        recipient: tracking_data.email.clone(),
        subject: format!("Your {report_name} Report: {start} - {end}"),
        body: report_email_body(
            &report_name,
            tracking_data.report_type.email_description(),
            &start,
            &end,
            download_url,
            &expiry_wording(config.download_url_expiry_hours),
        ),
    };

    for recipient in email_recipients(tracking_data, &config.email_bcc) {
        state
            .email_client
            .compose_and_send_email(
                crate::utils::user::get_base_url(state),
                Box::new(ReportEmail {
                    recipient: recipient.clone(),
                    ..email.clone()
                }),
                state.conf.proxy.https_url.as_ref(),
            )
            .await
            .change_context(AnalyticsError::UnknownError)
            .attach_printable("Failed to send the analytics report email")?;

        tracking_data.delivered_to.push(recipient);
        persist_tracking_data(state, process_id, tracking_data).await?;
    }

    Ok(())
}

#[cfg(not(feature = "email"))]
async fn send_emails(
    _state: &SessionState,
    _process_id: &str,
    _tracking_data: &mut AnalyticsReportTrackingData,
    _download_url: &str,
) -> CustomResult<(), AnalyticsError> {
    Err(report!(AnalyticsError::NotImplemented(
        "Emailing analytics reports without the email feature"
    )))
}

/// The requester first, then the other requested addresses, then the BCC list, each once and
/// skipping any an earlier attempt reached.
#[cfg(any(feature = "email", test))]
fn email_recipients(tracking_data: &AnalyticsReportTrackingData, bcc: &[Email]) -> Vec<Email> {
    let mut recipients: Vec<Email> = Vec::new();
    let requested = tracking_data.request.emails.iter().flatten();
    for email in std::iter::once(&tracking_data.email)
        .chain(requested)
        .chain(bcc)
    {
        let seen = recipients
            .iter()
            .chain(&tracking_data.delivered_to)
            .any(|existing| existing.peek().eq_ignore_ascii_case(email.peek()));
        if !seen {
            recipients.push(email.clone());
        }
    }
    recipients
}

#[cfg(feature = "email")]
#[derive(Clone)]
struct ReportEmail {
    recipient: Email,
    subject: String,
    body: String,
}

#[cfg(feature = "email")]
#[async_trait::async_trait]
impl external_services::email::EmailData for ReportEmail {
    async fn get_email_data(
        &self,
        _base_url: &str,
    ) -> CustomResult<external_services::email::EmailContents, external_services::email::EmailError>
    {
        Ok(external_services::email::EmailContents {
            subject: self.subject.clone(),
            body: external_services::email::IntermediateString::new(self.body.clone()),
            recipient: self.recipient.clone(),
        })
    }
}

/// The Lambda's HTML body, with the values escaped.
#[cfg(feature = "email")]
fn report_email_body(
    report_name: &str,
    description: &str,
    start: &str,
    end: &str,
    download_url: &str,
    expiry: &str,
) -> String {
    let report_name = escape_html(report_name);
    let download_url = escape_html(download_url);
    format!(
        "<p>Please find the {description} report for the period of {start} to {end}.<br>\n\
         This file provides a comprehensive overview of {description} processed via Hyperswitch during this time frame.\n\
         <br><br>Access your report here: <a href=\"{download_url}\">Download {report_name} Report</a>.\n\
         <br>(The link expires in {expiry})\n\
         <br>If you have any questions or require further assistance, please don't hesitate to reach out to us at <a href=\"mailto:hyperswitch@juspay.in\">hyperswitch@juspay.in</a>.\n\
         <br><br>Best regards,<br>\n\
         Hyperswitch Team</p>"
    )
}

/// The link's lifetime as the email words it: "7 days" for the default 168 hours.
#[cfg(any(feature = "email", test))]
fn expiry_wording(hours: u32) -> String {
    match (hours % 24, hours / 24) {
        (0, 1) => "1 day".to_owned(),
        (0, days) if days > 1 => format!("{days} days"),
        _ if hours == 1 => "1 hour".to_owned(),
        _ => format!("{hours} hours"),
    }
}

#[cfg(feature = "email")]
fn escape_html(value: &str) -> String {
    value
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
}

/// Saves `tracking_data` on the task. The business status stays `Pending` until the task finishes,
/// since the consumer skips any task whose business status is anything else.
pub(crate) async fn persist_tracking_data(
    state: &SessionState,
    process_id: &str,
    tracking_data: &AnalyticsReportTrackingData,
) -> CustomResult<(), AnalyticsError> {
    let value = serde_json::to_value(tracking_data)
        .change_context(AnalyticsError::UnknownError)
        .attach_printable("Failed to serialize analytics report tracking data")?;

    state
        .store
        .as_scheduler()
        .process_tracker_update_process_status_by_ids(
            vec![process_id.to_owned()],
            storage::ProcessTrackerUpdate::Update {
                name: None,
                retry_count: None,
                schedule_time: None,
                tracking_data: Some(value),
                business_status: None,
                status: None,
                updated_at: Some(date_time::now()),
            },
        )
        .await
        .change_context(AnalyticsError::UnknownError)
        .attach_printable("Failed to save analytics report progress")?;

    Ok(())
}

#[cfg(test)]
#[allow(clippy::unwrap_used)]
mod tests {
    use super::*;

    fn tracking_data(auth: AuthInfo, emails: Option<Vec<Email>>) -> AnalyticsReportTrackingData {
        AnalyticsReportTrackingData {
            job_id: "report_abc".to_owned(),
            report_type: AnalyticsReportType::V1Payments,
            request: ReportRequest {
                time_range: common_utils::types::TimeRange {
                    start_time: time::macros::datetime!(2026-10-01 00:00:00),
                    end_time: Some(time::macros::datetime!(2026-10-07 23:59:59.999)),
                },
                emails,
                return_url: None,
                #[cfg(feature = "v2")]
                report_type: Default::default(),
                columns: None,
            },
            auth,
            key_store_merchant_id: None,
            email: Email::try_from("owner@example.com".to_owned()).unwrap(),
            file_key: String::new(),
            upload_id: None,
            row_count: None,
            delivered_to: Vec::new(),
        }
    }

    fn profile_auth() -> AuthInfo {
        AuthInfo::ProfileLevel {
            org_id: id_type::OrganizationId::try_from(std::borrow::Cow::from("org_1")).unwrap(),
            merchant_id: id_type::MerchantId::try_from(std::borrow::Cow::from("merchant_1"))
                .unwrap(),
            profile_ids: vec![
                id_type::ProfileId::try_from(std::borrow::Cow::from("pro_1")).unwrap(),
            ],
            processor_merchant_id: None,
        }
    }

    #[test]
    fn file_key_follows_lambda_layout() {
        let data = tracking_data(profile_auth(), None);
        assert_eq!(
            file_key("analytics_reports", &data),
            "analytics_reports/org_1/merchant_1/pro_1/v1_payments/report_abc/\
             v1_payments_report_20261001000000_20261007235959.csv"
        );
    }

    #[test]
    fn webhook_body_keeps_lambda_shape() {
        let data = tracking_data(profile_auth(), None);
        let body = webhook_body(
            &data,
            ReportWebhookData::Completed {
                report_type: "payment_report",
                start_date_utc: reports::format_timestamp(data.start_time()),
                end_date_utc: reports::format_timestamp(data.end_time()),
                download_url: "https://bucket.example/key?X-Amz-Signature=ab",
                expires_in_hours: 168,
            },
        )
        .unwrap();

        // Field order and names follow build_webhook_payload in
        // weekly_payment_report_generator_step_2.
        assert_eq!(
            String::from_utf8(body.clone()).unwrap(),
            r#"{"org_id":"org_1","merchant_id":"merchant_1","profile_id":"pro_1","data":{"report_type":"payment_report","start_date_utc":"2026-10-01T00:00:00.000Z","end_date_utc":"2026-10-07T23:59:59.999Z","download_url":"https://bucket.example/key?X-Amz-Signature=ab","expires_in_hours":168},"event":"report_generation.completed"}"#
        );
        // Python: hmac.new(b"whsec_test_key", body, hashlib.sha512).hexdigest()
        assert_eq!(
            webhook_signature("whsec_test_key", &body).unwrap(),
            "76f475de13962c74f934f8dc2e21a88b2ae3d5f3ba825e523a15089c90dd5251ae895f87aa4d1c8bffc60004fdfbc546cd9666c4946640876d44a20fc8577ed1"
        );
    }

    #[test]
    fn failed_webhook_body_keeps_lambda_shape() {
        let auth = AuthInfo::OrgLevel {
            org_id: id_type::OrganizationId::try_from(std::borrow::Cow::from("org_1")).unwrap(),
        };
        let body = webhook_body(
            &tracking_data(auth, None),
            ReportWebhookData::Failed {
                code: "internal_server_error",
                message: "We could not generate the report due to a internal server error. Please request the report again.",
            },
        )
        .unwrap();

        assert_eq!(
            String::from_utf8(body).unwrap(),
            r#"{"org_id":"org_1","merchant_id":null,"data":{"code":"internal_server_error","message":"We could not generate the report due to a internal server error. Please request the report again."},"event":"report_generation.failed"}"#
        );
    }

    #[test]
    fn expiry_wording_matches_lambda_for_default() {
        assert_eq!(expiry_wording(168), "7 days");
        assert_eq!(expiry_wording(24), "1 day");
        assert_eq!(expiry_wording(36), "36 hours");
        assert_eq!(expiry_wording(1), "1 hour");
    }

    #[test]
    fn email_recipients_are_deduplicated_and_skip_delivered() {
        let email = |value: &str| Email::try_from(value.to_owned()).unwrap();
        let mut data = tracking_data(
            profile_auth(),
            Some(vec![email("Owner@example.com"), email("ops@example.com")]),
        );
        data.delivered_to = vec![email("ops@example.com")];

        let recipients = email_recipients(&data, &[email("audit@example.com")]);
        let recipients = recipients
            .iter()
            .map(|e| e.peek().as_str())
            .collect::<Vec<_>>();
        assert_eq!(recipients, ["owner@example.com", "audit@example.com"]);
    }
}
